awk -F, 'NR>1{n++; sh+=$2; if($2>mh)mh=$2; if($6>mj)mj=$6; if($8>mr)mr=$8; if($9>mt)mt=$9; if($10>mc)mc=$10; if($11>me)me=$11; if($12>mv)mv=$12; if($13>ma)ma=$13; if($14>mp)mp=$14; if($15>ms)ms=$15} END{printf "rows=%d | cpu_host avg=%.1f max=%.1f | cpu_jvb max=%.0f | rx max=%.1f tx max=%.1f Mbit/s | conf max=%d endpoints max=%d video_senders max=%d audio max=%d | stress max=%.3f\n",n,sh/n,mh,mj,mr,mt,mc,me,mv,ma,ms}' "$1"
